CREATE TABLE IF NOT EXISTS assessmentResponses (id INT PRIMARY KEY AUTO_INCREMENT, assessmentId INT NOT NULL, userId INT NOT NULL, responses JSON, status ENUM('draft', 'submitted', 'reviewed') DEFAULT 'draft', submittedAt DATETIME, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_assessment_response (assessmentId));
CREATE TABLE IF NOT EXISTS complianceLogs (id INT PRIMARY KEY AUTO_INCREMENT, organizationId INT NOT NULL, action VARCHAR(255) NOT NULL, description TEXT, userId INT, entityType VARCHAR(100), entityId INT, status ENUM('pending', 'approved', 'rejected') DEFAULT 'pending', createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX idx_org_compliance (organizationId));
CREATE TABLE IF NOT EXISTS auditLogs (id INT PRIMARY KEY AUTO_INCREMENT, organizationId INT NOT NULL, action VARCHAR(255) NOT NULL, entityType VARCHAR(100), entityId INT, userId INT, changes JSON, ipAddress VARCHAR(45), userAgent TEXT, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX idx_org_audit (organizationId), INDEX idx_audit_timestamp (createdAt));

